const channels = [
  { id: 'UCsBjURrPoezykLs9EqgamOA', name: 'Fireship',           cat: 'Tech/Dev' },
  { id: 'UCHlNU7kIZhRgSbhHvFoy72w', name: 'Hugging Face',       cat: 'AI Tools' },
  { id: 'UCbfYPyITQ-7l4upoX8nvctg', name: 'Two Minute Papers',  cat: 'AI Research' },
  { id: 'UCNJ1Ymd5yFuUPtn21xtRbbw', name: 'AI Explained',       cat: 'AI News' },
  { id: 'UCSHZKyawb77ixDdsGog4iWA', name: 'Lex Fridman',        cat: 'Tech/AI/Business' },
  { id: 'UCxIJaCMEptJjxmmQgGFsnCg', name: 'Y Combinator',       cat: 'Startup/Business' },
  { id: 'UCnxrdFPXJMeHru_b4Q_vTPQ', name: 'NetworkChuck',       cat: 'Tech/Networking' },
  { id: 'UCZHmQk67mSJgfCCTn7xBfew', name: 'Yannic Kilcher',     cat: 'AI/ML Deep Dive' },
  { id: 'UCBJycsmduvYEL83R_U4JriQ', name: 'MKBHD',             cat: 'Tech Reviews' },
  { id: 'UC9-y-6csu5WGm29I7JiwpnA',  name: 'Computerphile',     cat: 'CS/Tech' },
  { id: 'UCCjyq_K1Xwfg8Lndy7lKMpA', name: 'TechCrunch',         cat: 'Tech News' },
  { id: 'UCESLZhusAkFfsNsApnjF_Cg', name: 'All-In Podcast',     cat: 'B2B/Startup' }
];

const rssFeeds = channels.map(c => ({
  channelId:   c.id,
  channelName: c.name,
  category:    c.cat,
  rssUrl:      'https://www.youtube.com/feeds/videos.xml?channel_id=' + c.id
}));

const FIRECRAWL_KEY = 'fc-471db502e79143e0982f3d2638b8ccdb';
const CLAUDE_KEY    = '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';
const CLAUDE_MODEL  = 'claude-sonnet-4-6';
const DIGEST_EMAIL  = 'countrycoveinc@gmail.com';
const cutoff = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
const today  = new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' });

const manualVideoUrls = [
  'https://www.youtube.com/watch?v=aircAruvnKk'
];

console.log('[Config] ' + rssFeeds.length + ' channels | cutoff: ' + cutoff + ' | manual: ' + manualVideoUrls.length);
return [{ json: { channels, rssFeeds, FIRECRAWL_KEY, CLAUDE_KEY, CLAUDE_MODEL, DIGEST_EMAIL, cutoff, today, manualVideoUrls } }];

const cfg = $('Config: Channels + Keys').item.json;
let xmlText = '';
try { xmlText = $input.item.json?.data || $input.item.json?.body || (typeof $input.item.json === 'string' ? $input.item.json : '') || ''; } catch(e) { xmlText = ''; }

function xmlVal(str, tag) {
  const m = str.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\/' + tag + '>'));
  return m ? m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim() : '';
}

let trendingItems = [];
try {
  const itemRegex = /<item>([\s\S]*?)<\/item>/g;
  let m;
  while ((m = itemRegex.exec(xmlText)) !== null && trendingItems.length < 12) {
    const block = m[1];
    const title = xmlVal(block, 'title');
    const link  = xmlVal(block, 'link') || (block.match(/<link\s*\/>\s*([^<]+)/) || [])[1] || '';
    const desc  = xmlVal(block, 'description').replace(/<[^>]+>/g, '').slice(0, 300);
    const pub   = xmlVal(block, 'pubDate');
    if (title && title.length > 3) trendingItems.push({ source: 'TechCrunch', category: 'Trending Now', title, url: link, description: desc, published: pub || new Date().toISOString() });
  }
} catch(e) {
  console.log('[Trending] Parse failed: ' + e.message);
  trendingItems = [];
}

console.log('[Trending] ' + trendingItems.length + ' items from TechCrunch RSS (direct XML)');
return cfg.rssFeeds.map(feed => ({
  json: { ...feed, trendingItems, cfg }
}));

let prev = {};
try { prev = $('Split: One Channel at a Time').item.json || {}; } catch(e) { prev = {}; }
const safeChannel = prev.channelName || 'Unknown';
const safeCat     = prev.category    || 'General';
const safeCfg     = prev.cfg         || {};
const safeCutoff  = new Date(safeCfg.cutoff || (Date.now() - 72*3600*1000));
const safeTrend   = Array.isArray(prev.trendingItems) ? prev.trendingItems : [];

const EMPTY = [{ json: { channelName: safeChannel, category: safeCat, videos: [], trendingItems: safeTrend, cfg: safeCfg } }];

let xmlText = '';
try {
  const raw = $input.item.json;
  xmlText = raw?.data || raw?.body || (typeof raw === 'string' ? raw : '') || '';
} catch(e) { return EMPTY; }

if (!xmlText || xmlText.length < 50) {
  console.log('[RSS] ' + safeChannel + ': empty or too-short response');
  return EMPTY;
}

// Parse YouTube Atom XML — each video is an <entry> block
function atomVal(str, tag) {
  const m = str.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\/' + tag + '>'));
  return m ? m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim() : '';
}

const videos = [];
const entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
let m;
while ((m = entryRegex.exec(xmlText)) !== null) {
  try {
    const block = m[1];
    const published = atomVal(block, 'published');
    if (published) {
      const pubDate = new Date(published);
      if (pubDate < safeCutoff) continue;
    }
    const title   = atomVal(block, 'title');
    const linkM   = block.match(/<link[^>]+href="([^"]+)"/);
    const url     = linkM ? linkM[1] : '';
    const desc    = atomVal(block, 'media:description').replace(/<[^>]+>/g, '').slice(0, 200);
    if (!title || !url.includes('youtube.com/watch')) continue;
    videos.push({ source: 'Channel RSS', category: safeCat, channel: safeChannel, title, url, published: published || '', views: 0, description: desc });
  } catch(e) { continue; }
}

console.log('[RSS] ' + safeChannel + ': ' + videos.length + ' new videos (72h, direct XML)');
return [{ json: { channelName: safeChannel, category: safeCat, videos, trendingItems: safeTrend, cfg: safeCfg } }];

const allChannels = $input.item.json.allChannels || [];
let cfg = {};
for (const ch of allChannels) { if (ch.cfg && Object.keys(ch.cfg).length > 0) { cfg = ch.cfg; break; } }

const manualVideoUrls = Array.isArray(cfg.manualVideoUrls) ? cfg.manualVideoUrls : [];
const manualVideos = [];

function extractVideoId(url) {
  const m = url.match(/(?:v=|youtu\.be\/)([A-Za-z0-9_-]{11})/);
  return m ? m[1] : null;
}

function msToTimestamp(ms) {
  const totalSecs = Math.floor(ms / 1000);
  const h = Math.floor(totalSecs / 3600);
  const m = Math.floor((totalSecs % 3600) / 60);
  const s = totalSecs % 60;
  return (h > 0 ? h + ':' : '') + (h > 0 ? String(m).padStart(2,'0') : m) + ':' + String(s).padStart(2,'0');
}

function sampleSegments(segs, max) {
  if (segs.length <= max) return segs;
  const step = segs.length / max;
  return Array.from({ length: max }, (_, i) => segs[Math.floor(i * step)]);
}

for (const url of manualVideoUrls) {
  const videoId = extractVideoId(url);
  let title = url;
  let transcript = '';
  let source = '';

  // Get title via YouTube oEmbed
  if (videoId) {
    try {
      const oe = await $helpers.httpRequest({ method: 'GET', url: 'https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v=' + videoId + '&format=json' });
      const d = typeof oe === 'string' ? JSON.parse(oe) : oe;
      if (d.title) title = d.title;
    } catch(e) { console.log('[Manual] oEmbed failed: ' + e.message); }
  }

  // Step 1: Supadata — strongest free transcript API, works from any server IP
  if (videoId && !transcript) {
    try {
      const resp = await $helpers.httpRequest({
        method: 'GET',
        url: 'https://api.supadata.ai/v1/youtube/transcript?url=https://www.youtube.com/watch?v=' + videoId + '&text=false'
      });
      const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
      if (data?.content && Array.isArray(data.content) && data.content.length > 0) {
        const allSegs = data.content
          .map(seg => '[' + msToTimestamp(seg.offset || 0) + '] ' + (seg.text || '').replace(/\n/g,' ').trim())
          .filter(l => l.length > 8);
        const sampled = sampleSegments(allSegs, 200);
        transcript = sampled.join('\n');
        source = 'Supadata API — ' + sampled.length + ' of ' + allSegs.length + ' segments (timestamped)';
        console.log('[Manual] Supadata: ' + allSegs.length + ' segs → ' + sampled.length + ' for ' + videoId);
      }
    } catch(e) { console.log('[Manual] Supadata failed: ' + e.message); }
  }

  // Step 2: YouTube Timedtext API
  if (videoId && !transcript) {
    try {
      const resp = await $helpers.httpRequest({
        method: 'GET',
        url: 'https://www.youtube.com/api/timedtext?v=' + videoId + '&lang=en&fmt=json3',
        headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36' }
      });
      const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
      if (data?.events && data.events.length > 0) {
        const allSegs = data.events
          .filter(e => e.segs)
          .map(e => '[' + msToTimestamp(e.tStartMs) + '] ' + e.segs.map(s => (s.utf8 || '').replace(/\n/g,' ')).join('').trim())
          .filter(l => l.length > 8);
        const sampled = sampleSegments(allSegs, 200);
        transcript = sampled.join('\n');
        source = 'YouTube Timedtext API — ' + sampled.length + ' of ' + allSegs.length + ' segments';
        console.log('[Manual] Timedtext: ' + allSegs.length + ' segs → ' + sampled.length);
      }
    } catch(e) { console.log('[Manual] Timedtext failed: ' + e.message); }
  }

  // Step 3: Firecrawl full page scrape
  if (!transcript) {
    try {
      const resp = await $helpers.httpRequest({
        method: 'POST',
        url: 'https://api.firecrawl.dev/v1/scrape',
        headers: { 'Authorization': 'Bearer ' + cfg.FIRECRAWL_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({ url, formats: ['markdown'] })
      });
      const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
      const md = (data?.data?.markdown || '').slice(0, 5000);
      if (!title || title === url) title = data?.data?.metadata?.title || data?.data?.title || url;
      transcript = md;
      source = 'Firecrawl page scrape (no timestamps)';
      console.log('[Manual] Firecrawl fallback: ' + md.length + ' chars');
    } catch(e) {
      transcript = '(transcript unavailable — all 3 methods failed)';
      source = 'failed';
      console.log('[Manual] All methods failed for ' + url);
    }
  }

  manualVideos.push({ url, title, transcript, source, videoId });
}

console.log('[Manual] ' + manualVideos.length + ' video(s) processed');
return [{ json: { allChannels, manualVideos, cfg } }];

const allChannels  = $input.item.json.allChannels  || [];
const manualVideos = $input.item.json.manualVideos || [];

let allVideos     = [];
let trendingItems = [];
let cfg           = $input.item.json.cfg || {};

for (const ch of allChannels) {
  if (Array.isArray(ch.videos))        allVideos.push(...ch.videos);
  if (Array.isArray(ch.trendingItems)) trendingItems = ch.trendingItems;
  if (ch.cfg && ch.cfg.CLAUDE_MODEL)   cfg = ch.cfg;
}

allVideos.sort((a, b) => (b.views || 0) - (a.views || 0));
const totalNew = allVideos.length;
console.log('[Prompt] channel videos: ' + totalNew + ' | trending: ' + trendingItems.length + ' | manual: ' + manualVideos.length);

const channelSection = totalNew > 0
  ? allVideos.map(v =>
      '[' + v.category + '] ' + (v.channel||'') + ': "' + v.title + '"' +
      (v.views > 0 ? ' | ' + v.views.toLocaleString() + ' views' : '') +
      ' | ' + v.url
    ).join('\n')
  : 'No new videos from tracked channels in the last 72 hours.';

const trendingSection = trendingItems.length > 0
  ? trendingItems.map(t => t.title + (t.url ? ' | ' + t.url : '') + (t.description ? ' — ' + t.description.slice(0,120) : '')).join('\n')
  : 'Trending data unavailable today.';

const manualSection = manualVideos.length > 0
  ? manualVideos.map(v =>
      'TITLE: ' + v.title + '\nURL: ' + v.url + '\nSOURCE: ' + (v.source || 'unknown') + '\nTRANSCRIPT:\n' + (v.transcript || '(no transcript available)').slice(0, 6000)
    ).join('\n\n---\n\n')
  : 'No manually curated videos today.';

const prompt =
  'You are a sharp tech + AI + business news curator. Today is ' + cfg.today + '.\n\n' +
  'Below is fresh YouTube content from the last 72 hours.\n\n' +
  '== TRENDING TECH/AI/BUSINESS WEB CONTENT ==\n' + trendingSection + '\n\n' +
  '== NEW VIDEOS FROM 12 TRACKED YOUTUBE CHANNELS ==\n' + channelSection + '\n\n' +
  '== MANUALLY CURATED VIDEOS (scraped transcript/content) ==\n' + manualSection + '\n\n' +
  '== YOUR TASK ==\n' +
  'Write a crisp professional daily digest. Use this exact structure:\n\n' +
  'HEADLINE OF THE DAY\n' +
  'One bold sentence — the single biggest story/trend right now.\n\n' +
  'TOP 5 MUST-WATCH\n' +
  'For each: title | channel | why it matters (2 sentences) | link\n\n' +
  'AI & AUTOMATION HIGHLIGHTS\n' +
  '3 bullet points — most important AI/automation developments\n\n' +
  'BUSINESS & STARTUP SIGNALS\n' +
  '2 bullet points — key business/startup/SaaS signals\n\n' +
  'WHAT TO BUILD TODAY\n' +
  '1 specific actionable automation or product idea from today content\n\n' +
  'QUOTE OF THE DAY\n' +
  'A memorable insight from today content\n\n' +
  'Tone: smart, no fluff, like a briefing from a senior colleague. Plain text for email.';

const claudeRequest = JSON.stringify({
  model:      cfg.CLAUDE_MODEL || 'claude-sonnet-4-6',
  max_tokens: 3000,
  messages:   [{ role: 'user', content: prompt }]
});

return [{ json: { ...cfg, allVideos, trendingItems, manualVideos, totalNew, claudeRequest } }];

function decode(r) {
  if (r?.content) return r;
  if (!r?._readableState) return r;
  try {
    const chunks = Array.isArray(r._readableState.buffer) ? r._readableState.buffer : [];
    const bytes  = [];
    for (const c of chunks) {
      const d = c?.data;
      if (Array.isArray(d)) bytes.push(...d);
      else if (d?.type === 'Buffer' && Array.isArray(d.data)) bytes.push(...d.data);
    }
    if (bytes.length) return JSON.parse(Buffer.from(bytes).toString('utf-8'));
  } catch(e) {}
  return r;
}

const claudeResp = decode($input.item.json);
const prev       = $('Code: Build Claude Prompt').item.json;
const digestText = claudeResp?.content?.[0]?.text || 'Digest generation failed — please retry.';

const digestHtml = digestText.split('\n').map(line => {
  if (!line.trim()) return '<br/>';
  const HEADINGS = ['HEADLINE OF THE DAY','TOP 5 MUST','AI & AUTO','BUSINESS &','WHAT TO BUILD','QUOTE OF'];
  if (HEADINGS.some(h => line.toUpperCase().startsWith(h))) {
    return '<h3 style="color:#7c3aed;margin:22px 0 6px;font-size:15px;font-weight:800;text-transform:uppercase;letter-spacing:1px;">' + line.trim() + '</h3>';
  }
  if (/^[•\-\d]/.test(line.trim())) {
    const linked = line.replace(/(https?:\/\/[^\s]+)/g,'<a href="$1" style="color:#a78bfa;">Watch →</a>');
    return '<p style="margin:5px 0 5px 12px;color:#e2e8f0;font-size:14px;">' + linked + '</p>';
  }
  const linked = line.replace(/(https?:\/\/[^\s]+)/g,'<a href="$1" style="color:#a78bfa;">$1</a>');
  return '<p style="margin:5px 0;color:#cbd5e1;font-size:14px;">' + linked + '</p>';
}).join('');

const emailHtml = '<div style="font-family:Inter,Arial,sans-serif;max-width:680px;margin:0 auto;background:#0f0a1e;border-radius:16px;overflow:hidden;">'
  + '<div style="background:linear-gradient(135deg,#7c3aed,#1d4ed8);padding:32px;">'
  + '<div style="font-size:36px;">📺</div>'
  + '<h1 style="margin:10px 0 4px;font-size:22px;font-weight:900;color:#fff;">Daily Tech + AI + Business Digest</h1>'
  + '<p style="color:rgba(255,255,255,0.8);margin:0;font-size:13px;">' + prev.today + ' &nbsp;·&nbsp; ' + prev.totalNew + ' channel videos &nbsp;·&nbsp; ' + (prev.trendingItems?.length || 0) + ' trending items</p>'
  + '</div>'
  + '<div style="padding:28px 32px;">' + digestHtml + '</div>'
  + '<div style="background:#0d0a1a;padding:14px;text-align:center;border-top:1px solid #1e1b4b;">'
  + '<p style="color:#4b5563;font-size:11px;margin:0;">🤖 JHD Advisor AI Digest · 12 Channels + Web Trending · <a href="https://jhdadvisor.com" style="color:#7c3aed;">jhdadvisor.com</a> · <a href="https://www.linkedin.com/in/jhd-adviser-08a183413/" style="color:#0a66c2;">LinkedIn</a></p>'
  + '</div></div>';

const subject = '📺 ' + prev.today + ' — AI+Tech+Business Digest (' + prev.totalNew + ' videos)';
console.log('[Email] Ready: ' + subject);
return [{ json: { ...prev, digestText, emailHtml, subject } }];
